"Polynomfunktion {0}. Grades. Der Graph ist eine Parabel. Für a {1} {2}: nach oben offen; a {3} {4}: nach unten offen. Scheitelpunkt bei xₛ = −b/({5}a). Hat genau einen Wendepunkt? Nein — Parabeln haben keinen Wendepunkt.": "Funkcja wielomianowa stopnia {0}. Wykresem jest parabola. Dla a {1} {2}: ramiona w górę; a {3} {4}: ramiona w dół. Wierzchołek w xₛ = −b/({5}a). Czy ma dokładnie jeden punkt przegięcia? Nie — parabole nie mają punktu przegięcia.",
