"Konstruieren": "Konstruuj",
"Lotfusspunkt": "Spodek prostopadłej",
"Lot": "Prostopadła",
"Parallele": "Równoległa",
"Winkelhalbierende": "Dwusieczna",
"Tangente": "Styczna",
"Dreieck": "Trójkąt",
"Schwerpunkt": "Środek ciężkości",
"Umkreismittelpunkt": "Środek okręgu opisanego",
"Inkreismittelpunkt": "Środek okręgu wpisanego",
"Höhenschnittpunkt": "Ortocentrum",
"Umkreis": "Okrąg opisany",
"Inkreis": "Okrąg wpisany",
"Messen": "Mierz",
"Winkel": "Kąt",
"Abstand Punkt–Gerade": "Odległość punktu od prostej",
"Skalarprodukt": "Iloczyn skalarny",
"Vektoren": "Wektory",
"Vektor": "Wektor",
"Ortsvektor": "Wektor wodzący",
"Projektion": "Rzut",
