"Partielle Integration oder Substitution": "Całkowanie przez części lub podstawienie",
"Die Fläche zwischen f und der x-Achse (oder zwischen f und g) wird an den Schnittstellen in Stücke geteilt. Stücke über der Achse (bzw. über g) sind grün, darunter orange.": "Pole między f a osią x (lub między f a g) dzielimy w punktach przecięcia na kawałki. Kawałki nad osią (lub nad g) są zielone, pod nią pomarańczowe.",
"Flächen zählen immer positiv: Beim Integral heben sich grüne und orange Stücke teilweise auf, bei der Fläche nicht.": "Pola liczą się zawsze dodatnio: w całce zielone i pomarańczowe kawałki częściowo się znoszą, w polu nie.",
