"Eine lineare Funktion {0} = m·x + q hat als Graph eine Gerade. Die Steigung m sagt, um wie viel y pro Schritt {1} nach rechts wächst (Steigungsdreieck), q ist der y-Achsenabschnitt.": "Funkcja liniowa {0} = m·x + q ma jako wykres prostą. Współczynnik kierunkowy m mówi, o ile y rośnie przy każdym kroku {1} w prawo (trójkąt nachylenia), q jest wyrazem wolnym (przecięcie z osią y).",
"Ziehe den violetten Punkt S, um q zu ändern, oder verändere m mit dem Regler. Die Wertetabelle zeigt, dass y bei jedem Schritt um m wächst.": "Przeciągnij fioletowy punkt S, aby zmienić q, lub zmień m suwakiem. Tabela wartości pokazuje, że y rośnie o m przy każdym kroku.",
