"Wegen {0} ist die Parabel nach oben geöffnet: Der Scheitel ist der <1>tiefste</1> Punkt (Minimum {2}).": "Ponieważ {0}, parabola jest otwarta ku górze: wierzchołek jest punktem <1>najniższym</1> (minimum {2}).",
