"Rechenweg: Potenzfunktion": "Rozwiązanie: funkcja potęgowa",
"Potenzfunktion mit natürlichem Exponenten": "Funkcja potęgowa z wykładnikiem naturalnym",
"<0>Symmetrie:</0> Setze {1} ein. Das Vorzeichen eines Produkts aus {2} Faktoren {3} hängt davon ab, ob {4} gerade oder ungerade ist.": "<0>Symetria:</0> Podstaw {1}. Znak iloczynu {2} czynników {3} zależy od tego, czy {4} jest parzyste, czy nieparzyste.",
"{0} ungerade: {1}, der Graph ist <2>punktsymmetrisch zum Ursprung</2>.": "{0} nieparzyste: {1}, wykres jest <2>symetryczny względem początku układu</2>.",
"<0>Gemeinsame Punkte:</0> Alle Potenzfunktionen gehen durch {1} und {2} und, weil {3} ungerade ist, durch {4}.": "<0>Punkty wspólne:</0> Wszystkie funkcje potęgowe przechodzą przez {1} i {2}, a ponieważ {3} jest nieparzyste, także przez {4}.",
"<0>Monotonie und Verlauf:</0> Der Graph steigt auf ganz {1} (streng monoton wachsend).": "<0>Monotoniczność i przebieg:</0> Wykres rośnie na całym {1} (ściśle rosnąca).",
"<0>Vergleich mit kleineren Exponenten:</0> Für {1} wird {2} mit wachsendem {3} kleiner, für {4} grösser. Darum liegen die Graphen zwischen {5} und {6} unter der Normalparabel und ausserhalb darüber. Je grösser {7}, desto flacher nahe {8} und desto steiler aussen.": "<0>Porównanie z mniejszymi wykładnikami:</0> Dla {1} wartość {2} ze wzrostem {3} maleje, dla {4} rośnie. Dlatego wykresy leżą między {5} a {6} pod normalną parabolą, a poza tym przedziałem nad nią. Im większe {7}, tym płaściej w pobliżu {8} i tym stromiej na zewnątrz.",
"<0>Wert an der Stelle</0> {1}:": "<0>Wartość w punkcie</0> {1}:",
