"n gerade:": "n parzyste:",
"fällt für": "maleje dla",
"steigt für": "rośnie dla",
"{0} gerade: {1}, der Graph ist <2>achsensymmetrisch zur y-Achse</2>.": "{0} parzyste: {1}, wykres jest <2>symetryczny względem osi y</2>.",
"<0>Gemeinsame Punkte:</0> Alle Potenzfunktionen gehen durch {1} und {2} und, weil {3} gerade ist, durch {4}.": "<0>Punkty wspólne:</0> Wszystkie funkcje potęgowe przechodzą przez {1} i {2}, a ponieważ {3} jest parzyste, także przez {4}.",
"<0>Monotonie und Verlauf:</0> Für {1} fällt der Graph, für {2} steigt er; im Ursprung liegt der tiefste Punkt (Minimum).": "<0>Monotoniczność i przebieg:</0> Dla {1} wykres maleje, dla {2} rośnie; w początku układu leży najniższy punkt (minimum).",
"{0} ist achsensymmetrisch, {1}, {2}": "{0} jest symetryczna osiowo, {1}, {2}",
"{0} ist ungerade: Der Graph ist die erste Winkelhalbierende, <1>punktsymmetrisch</1> zum Ursprung.": "{0} jest nieparzyste: Wykres to dwusieczna pierwszej ćwiartki, <1>symetryczna środkowo</1> względem początku układu.",
"Erlaubt sind a·(x−v)^n + h, a/(x−v)^n + h, a·√(x−v) + h und (x−v)^(m/n) + h.": "Dozwolone są a·(x−v)^n + h, a/(x−v)^n + h, a·√(x−v) + h oraz (x−v)^(m/n) + h.",
"Negative Exponenten: {0} = x⁻ⁿ = {1}/xⁿ. Bei x = {2} hat f eine Definitionslücke; die Achsen sind Asymptoten. Je grösser |x|, desto näher kommt f der {3}.": "Ujemne wykładniki: {0} = x⁻ⁿ = {1}/xⁿ. W x = {2} funkcja f ma lukę w dziedzinie; osie są asymptotami. Im większe |x|, tym bliżej f zbliża się do {3}.",
"Ziehe den Punkt P nahe an die y-Achse oder weit nach aussen und beobachte die Werte. Gerades n: beide Äste oben; ungerades n: einer oben, einer unten.": "Przeciągnij punkt P blisko osi y lub daleko na zewnątrz i obserwuj wartości. Parzyste n: obie gałęzie u góry; nieparzyste n: jedna u góry, jedna u dołu.",
"{0} <1>Andere Exponenten zeigen</1>": "{0} <1>Pokaż inne wykładniki</1>",
