"Verhalten": "Zachowanie",
"Rechenweg: Negativer Exponent": "Rozwiązanie: ujemny wykładnik",
"Potenzfunktion mit negativem Exponenten": "Funkcja potęgowa z ujemnym wykładnikiem",
"<0>Definitionsbereich:</0> Der Nenner darf nicht {1} werden, also ist {2} ausgeschlossen (Definitionslücke, Polstelle).": "<0>Dziedzina:</0> Mianownik nie może być równy {1}, więc {2} jest wykluczone (luka w dziedzinie, biegun).",
"<0>Symmetrie:</0> {1}: achsensymmetrisch zur {2}-Achse.": "<0>Symetria:</0> {1}: symetria względem osi {2}.",
"<0>Verhalten nahe der Definitionslücke:</0> Nähert sich {1} der {2}, wird der Nenner winzig und der Bruch riesig.": "<0>Zachowanie w pobliżu luki w dziedzinie:</0> Gdy {1} zbliża się do {2}, mianownik staje się bardzo mały, a ułamek bardzo duży.",
"<0>Verhalten für grosse Beträge:</0> Für grosse {1} wird der Nenner riesig, der Bruch geht gegen {2}, ohne {3} zu erreichen.": "<0>Zachowanie dla dużych wartości bezwzględnych:</0> Dla dużych {1} mianownik staje się bardzo duży, ułamek dąży do {2}, nie osiągając {3}.",
"Senkrechte Asymptote {0} ({1}-Achse) und waagrechte Asymptote {2} ({3}-Achse)": "Asymptota pionowa {0} (oś {1}) i asymptota pozioma {2} (oś {3})",
"<0>Gemeinsame Punkte:</0> {1} und {2}. Für {3} ist {4}, für {5} ist {6}.": "<0>Punkty wspólne:</0> {1} i {2}. Dla {3} jest {4}, dla {5} jest {6}.",
"<0>Symmetrie:</0> {1}: punktsymmetrisch zum Ursprung.": "<0>Symetria:</0> {1}: symetria środkowa względem początku układu.",
"ist nicht definiert": "nie jest określone",
"Die Wurzelfunktion ⁿ√x ist die Umkehrfunktion von xⁿ: Ihr Graph ist das Spiegelbild an der Winkelhalbierenden y = x. In Potenzschreibweise ist ⁿ√x = x^({0}/n), allgemein x^(m/n) = ⁿ√(xᵐ).": "Funkcja pierwiastkowa ⁿ√x jest funkcją odwrotną do xⁿ: Jej wykres jest odbiciem względem prostej y = x. W zapisie potęgowym ⁿ√x = x^({0}/n), ogólnie x^(m/n) = ⁿ√(xᵐ).",
"Ziehe den Punkt P auf der Potenzfunktion: Sein Spiegelbild P′ liegt auf der Wurzelfunktion. Wähle n und einen Zähler m für den rationalen Exponenten.": "Przeciągnij punkt P po funkcji potęgowej: Jego odbicie P′ leży na funkcji pierwiastkowej. Wybierz n oraz licznik m wykładnika wymiernego.",
