"Gleichung {0} = y₀ lösen: Die Potenz wird isoliert, dann entscheidet die Fallunterscheidung (gerade/ungerade, Wurzel, negative rechte Seite), wie viele Lösungen es gibt. Die Lösungen sind die Schnittstellen mit der Geraden y = y₀.": "Rozwiązanie równania {0} = y₀: Potęgę wyznaczamy, a potem rozbicie na przypadki (parzysta/nieparzysta, pierwiastek, ujemna prawa strona) decyduje, ile jest rozwiązań. Rozwiązania to odcięte punktów przecięcia z prostą y = y₀.",
"Ziehe die orange Gerade auf und ab und beobachte, wann es zwei, eine oder keine Lösung gibt. Der Rechenweg rechts passt sich an.": "Przeciągaj pomarańczową prostą w górę i w dół i obserwuj, kiedy są dwa rozwiązania, jedno lub żadne. Rozwiązanie po prawej dostosowuje się.",
