"Flächen mit Rechtecken annähern, Integralfunktion und Hauptsatz, Stammfunktionen mit Regeln. Dazu Flächen zwischen Kurven und Rotationskörper.": "Przybliżanie pól prostokątami, funkcja całkowa i twierdzenie podstawowe, funkcje pierwotne według reguł. Do tego pola między krzywymi i bryły obrotowe.",
