"Folgen explizit und rekursiv, arithmetische und geometrische Folgen, Reihen und Summenzeichen, Grenzwert, unendliche geometrische Reihe, vollständige Induktion": "Ciągi jawne i rekurencyjne, ciągi arytmetyczne i geometryczne, szeregi i znak sumy, granica, nieskończony szereg geometryczny, indukcja matematyczna",
"Folgen explizit und rekursiv, arithmetisch und geometrisch, Reihen mit dem Summenzeichen, Grenzwerte und vollständige Induktion – alles als Punkte zum Ziehen.": "Ciągi jawne i rekurencyjne, arytmetyczne i geometryczne, szeregi ze znakiem sumy, granice i indukcja matematyczna – wszystko jako punkty do przeciągania.",
