"Termumformungen als Bild: binomische Formeln, Ausmultiplizieren und Faktorisieren, Potenzen, Wurzeln und Logarithmen, Bruchterme und Gleichungen.": "Przekształcanie wyrażeń na rysunku: wzory skróconego mnożenia, mnożenie nawiasów i rozkład na czynniki, potęgi, pierwiastki i logarytmy, wyrażenia wymierne i równania.",
"Konstruieren wie mit Zirkel und Lineal: Punkte, Geraden, Kreise und Dreiecke mit ihren besonderen Linien und Punkten.": "Konstrukcje jak cyrklem i linijką: punkty, proste, okręgi i trójkąty wraz z ich szczególnymi liniami i punktami.",
"Thema öffnen": "Otwórz temat",
"Ähnlichkeit": "Podobieństwo",
"Ein fixes Dreieck und sein Bild nach Verschiebung, Drehung um den Ursprung, Spiegelung an der x- oder y-Achse und zentrischer Streckung: Die Seitenverhältnisse stehen als Brüche daneben. Dazu Strahlensätze und das rechtwinklige Dreieck mit Höhe.": "Stały trójkąt i jego obraz po przesunięciu, obrocie wokół początku układu, symetrii względem osi x lub y oraz jednokładności: stosunki boków podane są obok jako ułamki. Do tego twierdzenie Talesa i trójkąt prostokątny z wysokością.",
