"Vektorgeometrie im Raum: Ebenen entdecken, Punkte und Vektoren, Geraden, Skalarprodukt und Winkel, Abstände und Kugel. Den Raum drehst du mit der Maus.": "Geometria wektorowa w przestrzeni: odkrywanie płaszczyzn, punkty i wektory, proste, iloczyn skalarny i kąt, odległości i sfera. Przestrzeń obracasz myszą.",
"Ebenen entdecken": "Odkrywanie płaszczyzn",
