"Zufallsexperimente zum Mitverfolgen: Würfel, Galtonbrett, Ziegenproblem und mehr. Relative Häufigkeiten nähern sich der Wahrscheinlichkeit.": "Doświadczenia losowe do śledzenia: kostki, deska Galtona, problem Monty'ego Halla i inne. Częstości względne zbliżają się do prawdopodobieństwa.",
