"Ungleichungen mit einer und zwei Variablen, Ungleichungssysteme und Planungspolygon, Zielfunktion, Niveaulinie und Optimum, Textaufgaben": "Nierówności z jedną i z dwiema zmiennymi, układy nierówności i wielokąt rozwiązań dopuszczalnych, funkcja celu, prosta poziomicowa i optimum, zadania tekstowe",
"Vom Text zum Optimum: Ungleichungen als Halbebenen, Planungspolygon mit Eckpunkten und eine Niveaulinie, die du bis zum Optimum verschiebst.": "Od tekstu do optimum: nierówności jako półpłaszczyzny, wielokąt rozwiązań dopuszczalnych z wierzchołkami i prosta poziomicowa, którą przesuwasz aż do optimum.",
