"<0>Seitenverhältnisse im Dreieck bleiben erhalten:</0> Teilt man zwei Seiten desselben Dreiecks, erhält man im Bild dasselbe wie im Original.": "<0>Stosunki boków w trójkącie są zachowane:</0> jeśli podzielisz przez siebie dwa boki tego samego trójkąta, w obrazie otrzymasz to samo co w oryginale.",
"<0>Entsprechende Seiten:</0> Jede Länge wird mit dem gleichen Faktor {1} multipliziert. Das Verhältnis Bild : Original ist für alle drei Seiten gleich:": "<0>Odpowiadające sobie boki:</0> każdą długość mnoży się przez ten sam współczynnik {1}. Stosunek obraz : oryginał jest taki sam dla wszystkich trzech boków:",
"<0>Winkel bleiben gleich:</0> Bei jeder Ähnlichkeitsabbildung sind entsprechende Winkel gleich gross.": "<0>Kąty się nie zmieniają:</0> w każdym przekształceniu przez podobieństwo odpowiadające sobie kąty są równe.",
"<0>Zusammenhang:</0> Punkt und Bildpunkt liegen auf einer Geraden durch {1}, und es gilt {2}. Entsprechende Seiten sind parallel.": "<0>Zależność:</0> punkt i jego obraz leżą na jednej prostej przechodzącej przez {1} i zachodzi {2}. Odpowiadające sobie boki są równoległe.",
"<0>Abbildung:</0> Zentrische Streckung von {1} aus mit {2}.": "<0>Przekształcenie:</0> jednokładność o środku {1} i {2}.",
