"ABC": "ABC",
"Wähle links eine Abbildung und vergleiche das Bild {0} mit dem Original {1}: Verschiebung, Drehung um den Ursprung, Spiegelung an der x- oder y-Achse und zentrische Streckung lassen alle Winkel gleich, alle Seiten stehen im Verhältnis |k|.": "Wybierz po lewej przekształcenie i porównaj obraz {0} z oryginałem {1}: przesunięcie, obrót wokół początku układu, symetria względem osi x lub y oraz jednokładność zachowują wszystkie kąty, a wszystkie boki pozostają w stosunku |k|.",
"{0} Ziehe die Ecken und die Griffe im Bild. Oben links wählst du die Ansicht, rechts steht der Rechenweg.": "{0} Przeciągaj wierzchołki i uchwyty na rysunku. U góry po lewej wybierasz widok, po prawej jest tok rozwiązania.",
"{0} mit Faktor {1}": "{0} ze współczynnikiem {1}",
"Die Dreiecke sind gleich orientiert: Drehen, Strecken und Verschieben genügen.": "Trójkąty mają tę samą orientację: wystarczą obrót, jednokładność i przesunięcie.",
"<0>Entsprechende Ecken in derselben Reihenfolge notieren</0>, dann sind die entsprechenden Seitenverhältnisse gleich:": "<0>Zapisz odpowiadające sobie wierzchołki w tej samej kolejności</0>, wtedy stosunki odpowiadających sobie boków są równe:",
"<0>Gleiche Winkel gefunden:</0> Die Ecken mit gleichen Winkeln entsprechen sich:": "<0>Znaleziono równe kąty:</0> wierzchołki o równych kątach odpowiadają sobie:",
"<0>Merke:</0> Zwei Dreiecke sind ähnlich, wenn sie in allen drei Winkeln übereinstimmen. Wegen der Winkelsumme {1} genügen zwei gleiche Winkel.": "<0>Zapamiętaj:</0> dwa trójkąty są podobne, jeśli mają równe wszystkie trzy kąty. Dzięki sumie kątów {1} wystarczą dwa równe kąty.",
