"Zwei Dreiecke (ABC und PQR) sind ähnlich, wenn sie in allen Winkeln übereinstimmen. Dann sind auch alle entsprechenden Seitenverhältnisse gleich. Gleiche Farben zeigen, welche Ecken und Seiten sich entsprechen.": "Dwa trójkąty (ABC i PQR) są podobne, jeśli mają wszystkie kąty równe. Wtedy równe są też wszystkie stosunki odpowiadających sobie boków. Te same kolory pokazują, które wierzchołki i boki sobie odpowiadają.",
