"<0>Zusammenhang:</0> Punkt und Bildpunkt liegen auf demselben Kreis um {1}, der Winkel {2} ist für jeden Punkt {3} (gegen den Uhrzeigersinn): {4}.": "<0>Zależność:</0> punkt i jego obraz leżą na tym samym okręgu o środku {1}; kąt {2} wynosi dla każdego punktu {3} (przeciwnie do ruchu wskazówek zegara): {4}.",
"<0>Abbildung:</0> Drehung um den Ursprung {1} um {2}.": "<0>Przekształcenie:</0> obrót wokół początku układu {1} o {2}.",
"Drehung um": "Obrót o",
"Positiver Winkel: gegen den Uhrzeigersinn. Du kannst das Bild auch an einer Ecke drehen.": "Kąt dodatni: przeciwnie do ruchu wskazówek zegara. Obraz możesz też obracać, chwytając za wierzchołek.",
"Drehung um den Ursprung O": "Obrót wokół początku układu O",
"Mit {0} sind Bild und Original sogar kongruent (deckungsgleich): Verschiebung, Drehung und Spiegelung ändern keine Länge. Erst die zentrische Streckung macht aus «kongruent» «ähnlich».": "Dla {0} obraz i oryginał są nawet przystające: przesunięcie, obrót i symetria nie zmieniają żadnej długości. Dopiero jednokładność zamienia „przystające” na „podobne”.",
"<0>Zusammenhang:</0> Jeder Punkt wandert um dieselbe Strecke in dieselbe Richtung: {1}. Die Strecken {2} sind parallel und gleich lang.": "<0>Zależność:</0> każdy punkt przesuwa się o ten sam odcinek w tym samym kierunku: {1}. Odcinki {2} są równoległe i równej długości.",
"<0>Abbildung:</0> Verschiebung um {1} nach rechts und {2} nach oben.": "<0>Przekształcenie:</0> przesunięcie o {1} w prawo i {2} w górę.",
"Verschiebung um": "Przesunięcie o",
"Du kannst das Bild auch mit der Maus verschieben.": "Obraz możesz też przesuwać myszą.",
"Jede Ecke und ihr Bild liegen gleich weit von der y-Achse entfernt. Ziehe die Ecken von ABC.": "Każdy wierzchołek i jego obraz leżą w tej samej odległości od osi y. Przeciągaj wierzchołki ABC.",
"<0>Zusammenhang:</0> Punkt und Bildpunkt liegen gleich weit von der Achse entfernt, ihre Verbindung steht senkrecht auf der Achse: {1}. Der Umlaufsinn kehrt sich um.": "<0>Zależność:</0> punkt i jego obraz leżą w tej samej odległości od osi, a łączący je odcinek jest prostopadły do osi: {1}. Kierunek obiegu się odwraca.",
