"nicht ähnlich": "niepodobne",
"nicht alle gleich: nicht ähnlich": "nie wszystkie równe: niepodobne",
"Fast ähnlich: Die Winkel unterscheiden sich noch um bis zu {0}°.": "Prawie podobne: kąty różnią się jeszcze nawet o {0}°.",
"Die Dreiecke sind nicht ähnlich.": "Trójkąty nie są podobne.",
"Die Dreiecke sind nicht ähnlich": "Trójkąty nie są podobne",
"Darum sind auch die Seitenverhältnisse <0>nicht</0> alle gleich:": "Dlatego stosunki boków też <0>nie</0> są wszystkie równe:",
"<0>Winkel vergleichen:</0> Auch bei der besten Zuordnung ({1}) unterscheiden sich die Winkel um bis zu {2}.": "<0>Porównanie kątów:</0> nawet przy najlepszym przyporządkowaniu ({1}) kąty różnią się nawet o {2}.",
"<0>Ähnliche Dreiecke:</0> Weil {1}, stimmen {2} und {3} in allen Winkeln überein (Scheitelwinkel bei {4}, Wechselwinkel an Parallelen).": "<0>Trójkąty podobne:</0> ponieważ {1}, trójkąty {2} i {3} mają wszystkie kąty równe (kąty wierzchołkowe przy {4}, kąty naprzemianległe przy prostych równoległych).",
"Zwei Geraden schneiden sich in {0}. {1} und {2} liegen auf der einen, {3} und {4} auf der anderen Geraden, auf verschiedenen Seiten von {5} (X-Figur).": "Dwie proste przecinają się w {0}. {1} i {2} leżą na jednej, {3} i {4} na drugiej prostej, po różnych stronach {5} (figura X).",
"Die Verhältnisse sind verschieden, weil {0}": "Stosunki są różne, ponieważ {0}",
"<0>Achtung:</0> {1} und {2} sind <3>nicht</3> parallel. Die Dreiecke {4} und {5} sind dann nicht ähnlich, die Strahlensätze gelten nicht:": "<0>Uwaga:</0> {1} i {2} <3>nie</3> są równoległe. Trójkąty {4} i {5} nie są wtedy podobne, a twierdzenie Talesa nie zachodzi:",
"nicht parallel": "nierównoległe",
"Ziehe D, bis CD parallel zu AB ist.": "Przeciągaj D, aż CD będzie równoległa do AB.",
"Nicht parallel: Die Strahlensätze gelten nicht.": "Nierównoległe: twierdzenie Talesa nie zachodzi.",
