"{0}Ähnlichkeit{1}": "{0}Podobieństwo{1}",
"Das Dreieck ABC bleibt fest. Sein Bild A′B′C′ entsteht durch Verschieben, Drehen um den Ursprung O, Spiegeln an der x- oder y-Achse und zentrisches Strecken von Z aus. Die ersten drei Abbildungen erhalten alle Längen (Bild und Original sind kongruent), die Streckung multipliziert jede Länge mit |k|. Die Winkel bleiben immer gleich.": "Trójkąt ABC pozostaje nieruchomy. Jego obraz A′B′C′ powstaje przez przesunięcie, obrót wokół początku układu O, symetrię względem osi x lub y oraz jednokładność o środku Z. Pierwsze trzy przekształcenia zachowują wszystkie długości (obraz i oryginał są przystające); jednokładność mnoży każdą długość przez |k|. Kąty zawsze pozostają takie same.",
