"{0}Folgen und Reihen{1}": "{0}Ciągi i szeregi{1}",
"Eine Folge ist eine durchnummerierte Liste von Zahlen a₁, a₂, a₃, … Explizit berechnet man jedes Glied direkt aus n, rekursiv aus dem Vorgänger. Die Glieder erscheinen als Punkte (n | aₙ).": "Ciąg to ponumerowana lista liczb a₁, a₂, a₃, … Wzorem jawnym każdy wyraz oblicza się bezpośrednio z n, rekurencyjnie – z poprzedniego wyrazu. Wyrazy pojawiają się jako punkty (n | aₙ).",
