"Rate gesucht (Zielbetrag vorgeben)": "Szukana rata (podaj kwotę docelową)",
"Jahreszins {0} % → konformer Zins {1} % pro Halbjahr, r = {2}": "Stopa roczna {0} % → stopa równoważna {1} % na półrocze, r = {2}",
