"Augen": "Liczba oczek",
"Kreisdiagramm (Anteile)": "Wykres kołowy (udziały)",
"Ein Hypothesentest prüft eine Annahme H₀ über eine Wahrscheinlichkeit p. Unter H₀ ist die Trefferzahl binomialverteilt. Der Ablehnungsbereich enthält die Werte, die unter H₀ zusammen höchstens die Wahrscheinlichkeit α (Signifikanzniveau) haben. Fehler {0}. Art: H₀ wird verworfen, obwohl sie stimmt.": "Test hipotezy sprawdza założenie H₀ o prawdopodobieństwie p. Przy H₀ liczba sukcesów ma rozkład dwumianowy. Obszar odrzucenia zawiera wartości, które przy H₀ mają łącznie co najwyżej prawdopodobieństwo α (poziom istotności). Błąd {0}. rodzaju: H₀ zostaje odrzucona, chociaż jest prawdziwa.",
"Poissonverteilung: Grenzfall der Binomialverteilung für n → ∞ und p → {0} bei festem Mittelwert λ = n·p. Normalverteilung: Für grosses n rücken die Säulen der Binomialverteilung, in Einheiten von σ gemessen, immer dichter zusammen und bilden die Glockenkurve; die Zufallsgrösse wird stetig (Satz von de Moivre und Laplace).": "Rozkład Poissona: przypadek graniczny rozkładu dwumianowego dla n → ∞ i p → {0} przy stałej średniej λ = n·p. Rozkład normalny: dla dużego n słupki rozkładu dwumianowego, mierzone w jednostkach σ, zbliżają się do siebie coraz bardziej i tworzą krzywą dzwonową; zmienna losowa staje się ciągła (twierdzenie de Moivre’a-Laplace’a).",
"Viele Messgrössen (Körpergrösse, Messfehler, Abfüllmengen) sind annähernd normalverteilt. Wahrscheinlichkeiten sind Flächen unter der Glockenkurve; sie hängen nur davon ab, wie viele Standardabweichungen σ die Grenze vom Mittelwert μ entfernt ist: z = (x − μ)/σ. Beidseitig: μ ± {0}σ enthält {1} %, μ ± {2}σ {3} %, μ ± {4}σ {5} %. Umgekehrt gehören zu {6} %, {7} % und {8} % die Grenzen {9}σ, {10}σ und {11}σ.": "Wiele wielkości mierzonych (wzrost, błędy pomiaru, ilości przy napełnianiu) ma w przybliżeniu rozkład normalny. Prawdopodobieństwa to pola pod krzywą dzwonową; zależą tylko od tego, o ile odchyleń standardowych σ granica jest oddalona od średniej μ: z = (x − μ)/σ. Obustronnie: μ ± {0}σ zawiera {1} %, μ ± {2}σ {3} %, μ ± {4}σ {5} %. Odwrotnie, wartościom {6} %, {7} % i {8} % odpowiadają granice {9}σ, {10}σ i {11}σ.",
"Eine Zufallsgrösse ordnet jedem Ergebnis eine Zahl zu (z. B. eine Auszahlung). Erwartungswert {0} = Σ xᵢ·{1}: der Mittelwert auf lange Sicht. Ein Spiel ist fair, wenn der Einsatz gleich dem Erwartungswert der Auszahlung ist.": "Zmienna losowa przyporządkowuje każdemu wynikowi liczbę (np. wypłatę). Wartość oczekiwana {0} = Σ xᵢ·{1}: średnia w długim okresie. Gra jest sprawiedliwa, gdy stawka jest równa wartości oczekiwanej wypłaty.",
"Die Poissonverteilung zählt, wie oft ein Ereignis in einem festen Zeitraum (oder auf einer Seite, Strecke, Fläche) eintritt, wenn die Ereignisse unabhängig und im Mittel gleich häufig auftreten: {0} = λᵏ/k! · e^(−λ). Dabei ist λ die mittlere Anzahl; Erwartungswert und Varianz sind beide λ. Für grosses n und kleines p nähert sie die Binomialverteilung mit λ = n·p an.": "Rozkład Poissona zlicza, ile razy zdarzenie zachodzi w ustalonym czasie (albo na stronie, odcinku, powierzchni), gdy zdarzenia są niezależne i średnio jednakowo częste: {0} = λᵏ/k! · e^(−λ). Tutaj λ to średnia liczba; wartość oczekiwana i wariancja są obie równe λ. Dla dużego n i małego p przybliża rozkład dwumianowy z λ = n·p.",
"Eine Bernoulli-Kette ist ein Versuch mit Treffer (p) und Niete, n-mal unabhängig wiederholt. Die Trefferzahl X ist binomialverteilt: {0} = (n über k)·pᵏ·({1} − p)ⁿ⁻ᵏ. Erwartungswert μ = n·p, Standardabweichung σ = √(n·p·({2} − p)).": "Schemat Bernoulliego to doświadczenie z sukcesem (p) i porażką, powtarzane n razy niezależnie. Liczba sukcesów X ma rozkład dwumianowy: {0} = (n po k)·pᵏ·({1} − p)ⁿ⁻ᵏ. Wartość oczekiwana μ = n·p, odchylenie standardowe σ = √(n·p·({2} − p)).",
"Mehrstufige Zufallsexperimente zeichnet man als Baumdiagramm. {0}. Pfadregel: Wahrscheinlichkeiten entlang eines Pfades multiplizieren. {1}. Pfadregel: Wahrscheinlichkeiten aller Pfade eines Ereignisses addieren. Ohne Zurücklegen ändern sich die Wahrscheinlichkeiten von Stufe zu Stufe.": "Wieloetapowe doświadczenia losowe rysuje się jako drzewo. Reguła {0}: mnożymy prawdopodobieństwa wzdłuż ścieżki. Reguła {1}: dodajemy prawdopodobieństwa wszystkich ścieżek zdarzenia. Bez zwracania prawdopodobieństwa zmieniają się z etapu na etap.",
"Jede Ansicht hat Beispiele; der Rechenweg rechts zeigt Formel und Zwischenschritte mit deinen Zahlen.": "Każdy widok ma przykłady; tok rozwiązania po prawej pokazuje wzór i kroki pośrednie z twoimi liczbami.",
"Normalverteilung: Grenze ziehen oder die Grenze x, die Anzahl σ bzw. die Prozentzahl eintippen – die anderen beiden rechnen mit. «Art» schaltet zwischen linksseitig, rechtsseitig, zwischen zwei Grenzen und beidseitig um. Die Knöpfe {0}σ, {1}σ, {2}σ und {3} %, {4} %, {5} % setzen die Merkzahlen.": "Rozkład normalny: przeciągnij granicę albo wpisz granicę x, liczbę σ lub procent – pozostałe dwie wielkości przeliczą się same. „Rodzaj” przełącza między lewostronnie, prawostronnie, między dwiema granicami i obustronnie. Przyciski {0}σ, {1}σ, {2}σ oraz {3} %, {4} %, {5} % ustawiają wartości warte zapamiętania.",
"«Grenzwerte»: Mit dem Regler oder «{0} n wachsen lassen» geht die Binomialverteilung in die Poisson- bzw. Normalverteilung über; der Rechenweg enthält die Herleitung der Formel mit den aktuellen Zahlen.": "„Granice”: suwakiem albo przyciskiem „{0} Niech n rośnie” rozkład dwumianowy przechodzi w rozkład Poissona lub normalny; tok rozwiązania zawiera wyprowadzenie wzoru z bieżącymi liczbami.",
"Datenanalyse: Eigene Werte tippst du links als Liste ein.": "Analiza danych: własne wartości wpisujesz po lewej jako listę.",
"Zahlen links ändern oder Punkte, Grenzen und Balken im Bild ziehen – beides gehört zusammen.": "Zmieniaj liczby po lewej albo przeciągaj punkty, granice i słupki na rysunku – jedno wiąże się z drugim.",
