"In der Urne liegen {0} rote ({1}) und {2} blaue ({3}) Kugeln. Es wird {4}-mal <5>mit</5> Zurücklegen gezogen. Die Wahrscheinlichkeiten bleiben auf jeder Stufe gleich.": "W urnie jest {0} kul czerwonych ({1}) i {2} niebieskich ({3}). Losujemy {4} razy <5>ze</5> zwracaniem. Prawdopodobieństwa są na każdym etapie takie same.",
"<0>Erwartungswert und Standardabweichung:</0> Im Mittel erwartet man {1} Treffer; die Werte streuen um {2}.": "<0>Wartość oczekiwana i odchylenie standardowe:</0> średnio oczekuje się {1} sukcesów; wartości rozpraszają się o około {2}.",
"Mit dem <0>Gegenereignis</0> ist es meist kürzer: «mindestens {1}» ist das Gegenteil von «höchstens {2}».": "Ze <0>zdarzeniem przeciwnym</0> jest zwykle krócej: „co najmniej {1}” jest przeciwieństwem „co najwyżej {2}”.",
"<0>Formel von Bernoulli:</0> Für genau {1} Treffer gibt es {2} Pfade, jeder mit der Wahrscheinlichkeit {3}.": "<0>Wzór Bernoulliego:</0> dla dokładnie {1} sukcesów jest {2} ścieżek, każda o prawdopodobieństwie {3}.",
"Ein Versuch mit «Treffer» (Wahrscheinlichkeit {0}) und «Niete» wird {1}-mal unabhängig wiederholt (Bernoulli-Kette). {2} zählt die Treffer: {3}.": "Doświadczenie z „sukcesem” (prawdopodobieństwo {0}) i „porażką” powtarza się {1} razy niezależnie (schemat Bernoulliego). {2} zlicza sukcesy: {3}.",
