"Ziehe {0} auf der Achse oder ändere links n und p: Die {1} sind die gesuchte Wahrscheinlichkeit. Beobachte, wie sich die Verteilung um {2} mit der Breite {3} legt; «{4} n wachsen lassen» zeigt, wie daraus die Glockenkurve wird.": "Przeciągnij {0} na osi albo zmień po lewej n i p: {1} to szukane prawdopodobieństwo. Obserwuj, jak rozkład układa się wokół {2} z szerokością {3}; „{4} Niech n rośnie” pokazuje, jak powstaje z niego krzywa dzwonowa.",
"Poisson": "Poisson",
"Wie die Binomialverteilung für wachsendes n in die Poissonverteilung übergeht, zeigt die Ansicht «Grenzwerte».": "Jak rozkład dwumianowy przechodzi w rozkład Poissona przy rosnącym n, pokazuje widok „Granice”.",
