"n (Versuche)": "n (próby)",
"Typische Beispiele: Anrufe pro Minute, Druckfehler pro Seite, Tore pro Spiel, Zerfälle pro Sekunde. Doppelter Zeitraum heisst doppeltes {0}.": "Typowe przykłady: połączenia na minutę, błędy drukarskie na stronę, gole na mecz, rozpady na sekundę. Dwukrotnie dłuższy czas oznacza dwukrotnie większe {0}.",
"<0>Erwartungswert und Standardabweichung:</0> Bei der Poissonverteilung sind Erwartungswert und Varianz beide gleich {1}.": "<0>Wartość oczekiwana i odchylenie standardowe:</0> w rozkładzie Poissona wartość oczekiwana i wariancja są obie równe {1}.",
"Formel:": "Wzór:",
"Die Poissonverteilung beschreibt, <0>wie oft ein Ereignis</0> in einem festen Zeitraum (oder auf einer Seite, einer Strecke, einer Fläche) eintritt, wenn die Ereignisse einzeln, unabhängig voneinander und im Mittel gleich häufig auftreten. {1} zählt die Ereignisse, {2} ist ihre <3>mittlere Anzahl</3>.": "Rozkład Poissona opisuje, <0>ile razy zdarzenie</0> zachodzi w ustalonym czasie (albo na stronie, odcinku, powierzchni), gdy zdarzenia występują pojedynczo, niezależnie od siebie i średnio jednakowo często. {1} zlicza zdarzenia, {2} to ich <3>średnia liczba</3>.",
