"<0>Faires Spiel:</0> Ein Spiel ist fair, wenn der Einsatz gleich dem Erwartungswert der Auszahlung ist. Dann gewinnt auf lange Sicht niemand.": "<0>Gra sprawiedliwa:</0> gra jest sprawiedliwa, gdy stawka jest równa wartości oczekiwanej wypłaty. Wtedy w długim okresie nikt nie wygrywa.",
"<0>Erwartungswert:</0> jeden Wert mit seiner Wahrscheinlichkeit gewichten und addieren. Er ist der Mittelwert der Auszahlung auf lange Sicht (der Schwerpunkt der Verteilung).": "<0>Wartość oczekiwana:</0> każdą wartość mnożymy przez jej prawdopodobieństwo i dodajemy. Jest to średnia wypłata w długim okresie (środek ciężkości rozkładu).",
"Die Zufallsgrösse {0} ist hier die Auszahlung pro Spiel. Ihre <1>Wahrscheinlichkeitsverteilung</1>:": "Zmienną losową {0} jest tu wypłata w jednej grze. Jej <1>rozkład prawdopodobieństwa</1>:",
